(() => {
'use strict';
const Q=window.QUESTIONS, $=s=>document.querySelector(s), app=$('#app');
const titles={3:'中國的產業轉型與區域差異',4:'全球化下的中國'};
const key='geo34-mastery-v1';let db={active:'訪客',profiles:{}},storageOK=true,session=null,pendingChapter=null;
try{const old=JSON.parse(localStorage.getItem(key));if(old&&old.profiles&&typeof old.active==='string')db=old;}catch{storageOK=false;}
function profile(){if(!Object.hasOwn(db.profiles,db.active))Object.defineProperty(db.profiles,db.active,{value:{scores:{},attempts:0,correct:0},enumerable:true,configurable:true,writable:true});return db.profiles[db.active];}
function studentName(){const st=profile().student;return st?st.className+' 班 '+st.seat+' 號 '+st.name:db.active;}
function grade(){const keys=Q.map(q=>profile().scores[q.id]).filter(x=>x&&typeof x.firstCorrect==='boolean');return {answered:keys.length,first:keys.filter(x=>x.firstCorrect).length*5};}
function score(q){const s=profile().scores[q.id];return Math.min(2,Math.max(0,Number(s?.correct)||0));}
function save(){try{localStorage.setItem(key,JSON.stringify(db));}catch{storageOK=false;}}
function escape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function list(ch){return ch==='all'?Q:Q.filter(q=>q.chapter===Number(ch));}
function stats(qs){return {done:qs.filter(q=>score(q)>=2).length,one:qs.filter(q=>score(q)===1).length,total:qs.length,points:qs.reduce((a,q)=>a+score(q),0)};}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function move(){window.scrollTo({top:0,behavior:'instant'});}
function openImage(src,title){$('#zoom-image').src=src;$('#viewer-title').textContent=title;$('#viewer').showModal();}
function home(){session=null;const s=stats(Q),p=profile();$('#profile').textContent=p.student?p.student.name+' · 學生資料':'填寫學生資料';
 app.innerHTML=`<section class="hero"><div><div class="eyebrow">YOUR NEXT GEOGRAPHY MILESTONE</div><h1>每一次練習，<br>都離精熟更近一步。</h1><p>跟著練習本原題，讀圖、思考，再選出答案。<br>每題在不同輪次累計答對 <b>2 次</b>，就能點亮你的精熟地圖。</p><span class="pill">原稿題目與圖片</span> <span class="pill">20 題 · 分輪練習</span></div><div class="hero-art" aria-hidden="true"><div class="globe"><div class="continent"></div></div><span class="art-note">探索世界，也掌握自己。 ↗</span></div></section>
 ${!storageOK?'<p class="storage-warning">此瀏覽器目前無法儲存進度；請開啟儲存權限，或在離開前匯出紀錄。</p>':''}
 <section class="identity-banner"><div><b>${p.student?escape(studentName()):'請先填寫班級、座號、姓名'}</b><p class="muted">首答成績：${grade().first} / 100 分 · 已首答 ${grade().answered} / 20 題（每題 5 分） · 累計正確率：${p.attempts?Math.round(p.correct/p.attempts*100):0}%</p><p id="delivery-status" class="muted" aria-live="polite"></p></div><div><button id="edit-student" class="secondary">${p.student?'切換學生':'填寫學生資料'}</button><button id="retry-delivery" class="quiet">重試回傳</button></div></section><section class="stats" aria-label="學習進度"><div class="stat"><strong>${s.done} <small>/ 20 題</small></strong><span>已精熟 · 答對兩次</span></div><div class="stat"><strong>${s.one} <small>題</small></strong><span>再答對一次就精熟</span></div><div class="stat"><strong>${s.points} <small>/ 40</small></strong><span>已累積的精熟印記</span></div></section>
 <div class="section-head"><h2>今天，從哪一課開始？</h2><span class="muted">${escape(studentName())}，接著上次的進度練習</span></div><section class="cards">${[3,4].map(ch=>{const c=stats(list(ch));return `<article class="chapter-card"><span class="chapter-no">CHAPTER 0${ch} · 第 ${ch} 課</span><h3>${titles[ch]}</h3><p>${ch===3?'農業轉變、工業發展與區域差異':'世界工廠、國際貿易與全球影響'}</p><div class="bar"><span style="width:${c.points/20*100}%"></span></div><div class="card-bottom"><span class="muted">${c.done} / 10 題已精熟</span><button class="secondary" data-start="${ch}">${c.done===10?'查看完成成果':'開始練習'} ↗</button></div></article>`;}).join('')}</section>
 <section class="mix-banner"><div><h3>第 3–4 課，混合挑戰。</h3><p>打散兩課題目，優先完成尚未精熟的題目。</p></div><button data-start="all">開始混合練習 →</button></section>
 <div class="rules"><span><b>01</b> 每輪每題只作答一次</span><span><b>02</b> 答錯看解析，下一輪再挑戰</span><span><b>03</b> 累計答對兩次，自動標記精熟</span></div>
 <div class="section-head"><h2>我的精熟地圖</h2><button id="export" class="quiet">匯出學習紀錄 ↓</button></div><section class="progress-list">${[3,4].map(ch=>`<div><p class="muted">第 ${ch} 課</p><div class="dots">${list(ch).map(q=>`<span class="dot ${score(q)===2?'done':score(q)===1?'one':''}" title="第 ${q.number} 題：已答對 ${score(q)} 次">${q.number}<br>${score(q)===2?'✓✓':score(q)===1?'✓·':'··'}</span>`).join('')}</div></div>`).join('')}</section><p class="legend">·· 尚未答對　 <span style="color:#ac7122">✓· 答對一次</span>　 <span style="color:#477342">✓✓ 已精熟</span></p>
 <div class="section-head"><h2>翻開課前整理</h2><div class="review-actions"><button data-review="3">第 3 課重點</button><button data-review="4">第 4 課重點</button></div></div><p class="muted">重點整理也是練習本原稿，方便練習前後複習。</p><div class="section-head"><span class="muted">已作答 ${p.attempts} 次 · 答對 ${p.correct} 次</span><button id="reset" class="quiet">重設此學生進度</button></div>`;
 app.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));app.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>openImage('assets/review-'+b.dataset.review+'.png','第 '+b.dataset.review+' 課重點整理'));
 $('#edit-student').onclick=identityDialog;$('#retry-delivery').onclick=()=>window.GEO_REPORTER.flush();updateDeliveryStatus();$('#export').onclick=exportReport;$('#reset').onclick=()=>{if(confirm('確定要重新開始「'+studentName()+'」的練習嗎？將建立新的練習紀錄，老師已收到的成績不會刪除。')){const st=profile().student;delete db.profiles[db.active];profile().student=st;save();home();}};move();}
function start(ch){if(!profile().student){pendingChapter=ch;identityDialog();return;}if(!profile().trainingId)profile().trainingId=crypto.randomUUID();session={ch,round:0,queue:[],index:0,selected:null,submitted:false,roundCorrect:0};nextRound();}
function nextRound(){session.queue=shuffle(list(session.ch).filter(q=>score(q)<2));session.index=0;session.round++;session.roundCorrect=0;if(!session.queue.length)return complete();showQuestion();}
function showQuestion(){const q=session.queue[session.index];session.selected=null;session.submitted=false;const s=stats(list(session.ch));
 app.innerHTML=`<div class="practice-head"><button class="quiet" id="exit">← 回到首頁</button><span class="muted">第 ${session.round} 輪 · ${session.index+1} / ${session.queue.length} 題</span></div><div class="practice-layout"><article class="question-card"><div class="question-top"><div><span class="pill">第 ${q.chapter} 課 · ${q.number<=5?'基礎題':'活用題'}</span><h2 style="font-size:18px;margin:8px 0 0">練習本第 ${q.number} 題</h2></div><button class="quiet" id="full-page">查看整頁 ↗</button></div><div class="question-images">${q.passage?`<div class="passage-wrap"><p class="passage-label">共用閱讀文章 · 請先閱讀，再回答下方題目</p><img src="${q.passage}" alt="第 ${q.chapter} 課題組共用閱讀文章，點擊放大" data-zoom></div>`:''}<img src="${q.image}" alt="第 ${q.chapter} 課第 ${q.number} 題，包含練習本原始文字、圖片及 A 到 D 選項，點擊放大" data-zoom></div><div class="source-note">練習本第 ${q.page} 頁 · 點擊題目圖片可放大</div></article><aside class="answer-panel"><span class="eyebrow">THINK · CHOOSE · MASTER</span><h2 style="margin-top:12px">你的答案是？</h2><p class="muted">依照原題的 A、B、C、D 選項作答。</p><div class="choice-grid">${['A','B','C','D'].map((x,i)=>`<button class="choice" data-choice="${i}" aria-pressed="false" aria-label="選項 ${x}">${x}</button>`).join('')}</div><button class="primary" id="submit" disabled>確認答案</button><div id="feedback" aria-live="polite"></div><div class="mini-progress"><p>這一題的精熟印記</p><div class="status-stars" id="stars">${marks(q)}</div><p id="count">累計答對 ${score(q)} / 2 次</p><div class="bar"><span style="width:${s.points/(s.total*2)*100}%"></span></div><p>本次範圍已有 ${s.done} / ${s.total} 題精熟</p><p>答錯不扣除已累積的答對次數。</p></div></aside></div>`;
 $('#exit').onclick=home;$('#full-page').onclick=()=>openImage('assets/page-'+q.pdfPage+'.png','練習本第 '+q.page+' 頁');app.querySelectorAll('[data-zoom]').forEach(im=>im.onclick=()=>openImage(im.src,'第 '+q.chapter+' 課 · 第 '+q.number+' 題原稿'));
 app.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.choice)));$('#submit').onclick=submit;move();}
function marks(q){return score(q)===2?'● ●':score(q)===1?'● ○':'○ ○';}
function choose(i){if(!session||session.submitted)return;session.selected=i;app.querySelectorAll('[data-choice]').forEach(b=>{const yes=Number(b.dataset.choice)===i;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes));});$('#submit').disabled=false;}
function submit(){if(!session||session.submitted||session.selected===null)return;session.submitted=true;const q=session.queue[session.index],ok=session.selected===q.answer,p=profile();
 const r=p.scores[q.id]||(p.scores[q.id]={correct:0,attempts:0,wrong:0});if(r.attempts===0){r.firstCorrect=ok;r.firstSelected=session.selected;}r.attempts++;p.attempts++;if(ok){r.correct=Math.min(2,r.correct+1);p.correct++;session.roundCorrect++;}else r.wrong++;r.lastAttempt=new Date().toISOString();save();if(p.student){try{window.GEO_REPORTER.enqueue({student:{...p.student},trainingId:p.trainingId,questionId:q.id,selected:session.selected});}catch(error){storageOK=false;console.error('成績佇列寫入失敗',error);}}
 app.querySelectorAll('[data-choice]').forEach(b=>{b.disabled=true;const i=Number(b.dataset.choice);b.classList.toggle('correct',i===q.answer);b.classList.toggle('wrong',i===session.selected&&!ok);});$('#submit').style.display='none';
 $('#feedback').innerHTML=`<div class="feedback ${ok?'':'bad'}"><strong>${ok?(score(q)===2?'✓ 這一題，精熟了！':'✓ 答對了！再累積一次。'):'再想一想，下輪再挑戰。'}</strong><p>正確答案：<b>${'ABCD'[q.answer]}</b></p><p>${q.explanation}</p><p class="muted">解析依教師版答案整理</p>${!storageOK?'<p>進度暫時無法儲存，請在離開前匯出紀錄。</p>':''}</div><button class="primary" id="next">${session.index+1===session.queue.length?'查看本輪結果':'下一題 →'}</button>`;
 $('#stars').textContent=marks(q);$('#count').textContent='累計答對 '+score(q)+' / 2 次';$('#next').onclick=()=>{session.index++;if(session.index>=session.queue.length)roundResult();else showQuestion();};}
function roundResult(){const s=stats(list(session.ch));if(s.done===s.total)return complete();app.innerHTML=`<section class="round-title"><div class="round-symbol">◎</div><div class="eyebrow">ROUND ${session.round} COMPLETE</div><h1>完成一輪，讓記憶更牢固。</h1><p>本輪答對 <b>${session.roundCorrect} / ${session.queue.length}</b> 題。<br>目前已有 <b>${s.done} / ${s.total}</b> 題精熟，還有 ${s.total-s.done} 題需要練習。</p><p class="muted">下一輪會重新打散尚未精熟的題目。<br>已精熟題目自動退出，專心練習還需要的部分。</p><button class="primary" id="continue">開始第 ${session.round+1} 輪 →</button><div class="action-row"><button id="back">休息一下，回首頁</button></div></section>`;$('#continue').onclick=nextRound;$('#back').onclick=home;move();}
function complete(){const qs=list(session.ch),s=stats(qs);app.innerHTML=`<section class="round-title"><div class="round-symbol">✺</div><div class="eyebrow">MASTERY ACHIEVED</div><h1>${session.ch==='all'?'兩課':'這一課'}全部精熟！</h1><p>${escape(studentName())}，你已讓 <b>${s.total} 題</b>每題都累計答對至少 <b>2 次</b>。<br>每一個精熟印記，都是你認真思考的成果。</p><div class="action-row"><button class="primary" id="back">回到精熟地圖</button><button id="export">匯出學習紀錄</button></div></section>`;$('#back').onclick=home;$('#export').onclick=exportReport;move();}
function exportReport(){const rows=[['班級','座號','姓名','課次','題號','練習本頁碼','首次是否答對','累計答對','作答次數','答錯次數','精熟狀態'],...Q.map(q=>{const s=profile().scores[q.id]||{};return[profile().student?.className||'',profile().student?.seat||'',profile().student?.name||db.active,q.chapter,q.number,q.page,typeof s.firstCorrect==='boolean'?(s.firstCorrect?'是':'否'):'未作答',score(q),s.attempts||0,s.wrong||0,score(q)>=2?'已精熟':'待練習'];})];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='地理第3-4課學習紀錄.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}
function identityDialog(){const st=profile().student||{};$('#student-class').value=st.className||'';$('#student-seat').value=st.seat||'';$('#student-name').value=st.name||'';$('#identity-error').textContent='';$('#profile-dialog').showModal();$('#student-class').focus();}
function updateDeliveryStatus(){const el=$('#delivery-status');if(!el)return;const d=window.GEO_REPORTER.status();el.textContent=!d.configured?'老師尚未設定 GAS 收件網址，答題會先保留在本機。':d.busy?'正在回傳成績…（尚有 '+d.pending+' 筆）':d.pending?'有 '+d.pending+' 筆等待確認回傳。'+(d.lastError||'網路恢復後會自動重試。'):d.confirmed?'GAS 已確認本次回傳，沒有待傳紀錄。':'沒有待回傳的答題紀錄。';}
window.addEventListener('geo-delivery-change',updateDeliveryStatus);
$('#home').onclick=e=>{e.preventDefault();home();};$('#profile').onclick=identityDialog;
$('#student-form').onsubmit=e=>{e.preventDefault();const className=$('#student-class').value.trim(),seat=String(Number($('#student-seat').value)),name=$('#student-name').value.trim();if(!className||!name||className.length>40||name.length>40||!/^\d{1,3}$/.test(seat)||Number(seat)<1){$('#identity-error').textContent='請完整填寫班級、正確座號與姓名。';return;}const st={className,seat,name};db.active=JSON.stringify([className,seat,name]);profile().student=st;if(!profile().trainingId)profile().trainingId=crypto.randomUUID();save();$('#profile-dialog').close();const ch=pendingChapter;pendingChapter=null;if(ch)start(ch);else home();};
$('#cancel-profile').onclick=()=>{pendingChapter=null;$('#profile-dialog').close();};$('#close-viewer').onclick=()=>$('#viewer').close();
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||!session||!$('#submit')||e.target.matches('input'))return;if(/^[1-4]$/.test(e.key)){choose(Number(e.key)-1);e.preventDefault();}else if(e.key==='Enter'){if(!session.submitted)submit();else $('#next')?.click();e.preventDefault();}});
profile();home();
})();
